  "ui.pauseBody": "আপনি এক মাসের জন্য সাবস্ক্রিপশন বিরতিতে রাখতে পারেন, কোনো পেমেন্ট ছাড়া। সবকিছু যেমন আছে তেমনই থাকবে, আর এক মাস পরে সাবস্ক্রিপশন নিজে থেকেই আবার চলবে।",
