  "ui.renewBody": "আপনার ট্রায়াল শেষ পর্যন্ত চলবে, এবং কোনো চার্জ হবে না।",
  "ui.renewBtn": "নবায়ন বন্ধ করুন এবং ট্রায়াল চালু রাখুন",
