  "ui.pauseBody": "O ka emisa peeletso ka kgwedi e le nngwe, o sa duele. Sengwe le sengwe se sala se ntse jalo, mme peeletso e tswelela ka boyona morago ga kgwedi.",
  "ui.pauseBtn": "Emisa ka kgwedi e le nngwe",
  "ui.renewTitle": "Ga go bothata, re tla tima go ntšhafatsa ka go iketsa",
  "ui.renewBody": "Teko ya gago e tla tswelela go fitlha kwa bokhutlong, mme ga go kitla go nna le tuelo.",
  "ui.renewBtn": "Tima go ntšhafatsa mme o tswelele ka teko",
  "ui.cancelsAtEnd": "E khanselwa kwa bokhutlong jwa nako ya tuelo",
  "ui.mistake": "Ke khanseditse ka phoso, tlogela peeletso e ntse",
  "demo.meaning2": "e sa tlwaelegang kgotsa e gakgamatsa.",
  "demo.example2": "Go ne ga tswa modumo o o gakgamatsang kwa marulelong.",
  "demo.originLang": "Selatini",
  "demo.originWord": "curiosus",
  "demo.originMeant": "kelotlhoko, o eletsa go itse",
  "demo.mySentence": "Katse ya me e e ratang go itse e ne ya bula mabokoso otlhe mo ntlong.",
  "demo.feedbackMsg": "Go siame, o dirisitse 'curious' sentle fela ka bokao jo bo nepagetseng.",
  "demo.moreEx1": "O ne a rata go itse ka mmapa wa bogologolo.",
  "demo.moreEx2": "Baithuti ba ba ratang go itse ba ithuta ka bonako.",
  "demo.familyAnswer": "curiosity, curiously",
  "demo.word2m": "o ipaakanyeditse go lebana le kotsi kgotsa botlhoko.",
  "demo.word3m": "lefelo le legolo thata la metsi a letswai.",
