  "demo.feedbackMsg": "Swi kahle, mi tirhisile 'curious' hi nhlamuselo leyi faneleke kahle.",
  "demo.moreEx1": "A a tsakela ku tiva hi mepe wa khale.",
  "demo.moreEx2": "Vadyondzi lava tsakaka ku tiva va dyondza hi ku hatlisa.",
  "demo.familyAnswer": "curiosity, curiously",
  "demo.word2m": "u lunghekele ku langutana ni khombo kumbe ku vaviseka.",
  "demo.word3m": "ndhawu leyikulu ngopfu ya mati ya munyu.",
  "demo.contextPos": "riendli",
  "demo.kw1m": "ra khale ngopfu",
  "demo.kw2m": "ku kuma ndlela",
  "demo.kw3m": "rikulu ngopfu",
