  "demo.originMeant": "u ṱhogomela, u ṱoḓa u ḓivha",
  "demo.mySentence": "Kati yanga i ṱoḓaho u ḓivha yo vula bogisi ḽiṅwe na ḽiṅwe nḓuni.",
  "demo.feedbackMsg": "Zwavhuḓi, no shumisa 'curious' nga nḓila yone kokotolo.",
  "demo.moreEx1": "O vha a tshi ṱoḓa u ḓivha nga ha mapa ya kale.",
  "demo.moreEx2": "Vhagudi vha ṱoḓaho u ḓivha vha guda nga u ṱavhanya.",
  "demo.familyAnswer": "curiosity, curiously",
  "demo.word2m": "o lugela u livhana na khombo kana vhuṱungu.",
  "demo.word3m": "fhethu ḽihulu vhukuma ḽa maḓi a munyu.",
